I used a greedy approach with a short lookahead, planned balloon by balloon. I have not compiled or run it against any data set.

**State.** A balloon's state is its row, column and altitude (0 means on the ground). Moving it is cheap: apply the altitude change, then add the wind vector at the new altitude. If the new row falls outside 0..R-1, the balloon is lost.

**Per-balloon planning.** For each balloon in turn, I run a DP over time with the full state (r, c, a) of up to 1e6 cells per turn. That is too much for 1000 turns and 1000 balloons, so I use a beam search instead:
- Each balloon keeps a beam of at most W states per turn, and states are deduplicated by (r, c, a).
- The score of a transition is the marginal gain at that turn: the number of target cells covered by this balloon at the end of the turn that are not already covered by earlier balloons.
- I keep a `cov[t][target]` bitmap of already-covered targets, which is 1e6 bytes.
- Computing the gain for a position costs O(L), and the cost over the whole run is B·T·W·3·L, which is far too much. To avoid this, I precompute for each cell (r, c) the list of targets within range. A target list is only needed per cell, so I use a grid of `cnt[t][cell]`, the number of uncovered targets in range of each cell at turn t. That grid is 1e9 entries, which is too big.

**Gain computation.** Instead, each gain is computed on the fly from a per-row bucket of targets. Targets are sorted by row, and for a position (r, c) I scan rows r-V..r+V and check each target's column distance. With L=1000 this costs at most about L checks. To cut this down, I choose the beam width W = 3 and count the work: B·T·W·3·L = 1000·1000·3·3·1000 = 9e9, which is too slow.

**Budget.** I make the work adaptive. The budget is about 1.5e9 simple operations, and I set W from that:
- Each state expansion costs roughly the number of targets near the cell, which is about L·(area / total area) on average, plus a constant of about 20.
- I measure the work as it goes, and balloons that would exceed the time limit fall back to W = 1 (a greedy walk).
- I check the clock with `clock()` and degrade W when needed.

**Reconstruction.** Each beam node stores a parent index and an action, per turn. For one balloon this is T·W nodes, which is small.

**Launch time.** A balloon on the ground at altitude 0 is itself a state, and it can stay on the ground with no coverage and no position. Its first transition to altitude 1 is the launch, and the beam handles that choice.

**Output.** The actions are stored in `out[t][b]`, and a lost balloon outputs 0 afterward. A grounded balloon outputs 0 until launch. Balloons whose best plan has a total gain of 0 stay on the ground, which is valid.

```cpp
#include <bits/stdc++.h>
using namespace std;
int R,C,A,L,V,B,T,rs,cs;
vector<int> wr,wc;
vector<pair<int,int>> tg;
vector<vector<int>> rowT;
vector<vector<char>> cov;
int tid[1000][1000];
static inline int gain(int t,int r,int c){
    int g=0;
    int lo=max(0,r-V),hi=min(R-1,r+V);
    for(int u=lo;u<=hi;u++){
        for(int id:rowT[u]){
            int v=tg[id].second;
            int d=abs(c-v);d=min(d,C-d);
            int dr=r-u;
            if(dr*dr+d*d<=V*V&&!cov[t][id])g++;
        }
    }
    return g;
}
struct Node{int r,c,a,par;signed char act;long long sc;};
int main(){
    scanf("%d %d %d",&R,&C,&A);
    scanf("%d %d %d %d",&L,&V,&B,&T);
    scanf("%d %d",&rs,&cs);
    tg.resize(L);rowT.assign(R,{});
    for(int i=0;i<L;i++){scanf("%d %d",&tg[i].first,&tg[i].second);rowT[tg[i].first].push_back(i);}
    wr.resize((size_t)A*R*C);wc.resize((size_t)A*R*C);
    for(size_t i=0;i<(size_t)A*R*C;i++){scanf("%d %d",&wr[i],&wc[i]);}
    cov.assign(T+1,vector<char>(L,0));
    vector<vector<signed char>> out(T,vector<signed char>(B,0));
    clock_t st=clock();
    for(int b=0;b<B;b++){
        double el=(double)(clock()-st)/CLOCKS_PER_SEC;
        double perBalloonLeft=(8.0-el)/(B-b);
        int W=3;
        if(perBalloonLeft<0.002)W=1;
        else if(perBalloonLeft>0.02)W=6;
        vector<vector<Node>> lay(T+1);
        lay[0].push_back({rs,cs,0,-1,0,0});
        for(int t=1;t<=T;t++){
            vector<Node> cand;
            auto&prev=lay[t-1];
            for(int i=0;i<(int)prev.size();i++){
                const Node&n=prev[i];
                for(int d=-1;d<=1;d++){
                    int na=n.a+d;
                    if(na<0||na>A)continue;
                    if(n.a==0&&d<0)continue;
                    if(n.a>0&&na<1)continue;
                    int nr=n.r,nc=n.c;long long g=0;
                    if(na>0){
                        size_t k=((size_t)(na-1)*R+n.r)*C+n.c;
                        nr=n.r+wr[k];
                        if(nr<0||nr>=R)continue;
                        nc=((n.c+wc[k])%C+C)%C;
                        g=gain(t,nr,nc);
                    }
                    cand.push_back({nr,nc,na,i,(signed char)d,n.sc+g});
                }
            }
            sort(cand.begin(),cand.end(),[](const Node&x,const Node&y){return x.sc>y.sc;});
            set<tuple<int,int,int>> seen;
            for(auto&n:cand){
                if((int)lay[t].size()>=W)break;
                if(n.a>0&&!seen.insert({n.r,n.c,n.a}).second)continue;
                lay[t].push_back(n);
            }
            if(lay[t].empty())break;
        }
        // find best final
        int bt=0;
        for(int t=T;t>=0;t--)if(!lay[t].empty()){bt=t;break;}
        int bi=0;
        for(int i=0;i<(int)lay[bt].size();i++)if(lay[bt][i].sc>lay[bt][bi].sc)bi=i;
        if(lay[bt][bi].sc<=0)continue;
        vector<int> idx(bt+1);
        int cur=bi;
        for(int t=bt;t>=1;t--){
            out[t-1][b]=lay[t][cur].act;
            idx[t]=cur;
            cur=lay[t][cur].par;
        }
        // replay to mark coverage
        int r=rs,c=cs,a=0;
        for(int t=1;t<=bt;t++){
            a+=out[t-1][b];
            if(a>0){
                size_t k=((size_t)(a-1)*R+r)*C+c;
                r+=wr[k];
                c=((c+wc[k])%C+C)%C;
                int lo=max(0,r-V),hi=min(R-1,r+V);
                for(int u=lo;u<=hi;u++)for(int id:rowT[u]){
                    int d=abs(c-tg[id].second);d=min(d,C-d);
                    int dr=r-u;
                    if(dr*dr+d*d<=V*V)cov[t][id]=1;
                }
            }
        }
        // remaining turns after bt: output 0 (altitude stays)
    }
    string s;
    for(int t=0;t<T;t++){
        s.clear();
        for(int b=0;b<B;b++){
            if(b)s+=' ';
            int v=out[t][b];
            if(v==-1)s+="-1";else s+=char('0'+v);
        }
        puts(s.c_str());
    }
}
